-- Stage 2 of 2: the clean, conformed rows the marts consume.

-- Source systems replay batches, so the same business key can
-- arrive more than once. Keep the most recently ingested version.
with deduplicated as (
    select
        *,
        row_number() over (partition by session_id order by ingested_at desc nulls last) as _row_rank
    from {{ ref('cln_fact_digital_sessions') }}
    where _dq_is_valid
)

select
    session_id,
    session_start_ts,
    session_end_ts,
    date_key,
    digital_user_id,
    device_type,
    event_count,
    duration_seconds,
    screens_viewed,
    is_bounce,
    converted,
    acquisition_channel,
    source_system_code,
    ingested_at,
    _cleansed_at
from deduplicated
where _row_rank = 1
